custom_css:
/* 作者：栗子*/
/* 禁商禁二传 */
/* 可二改 */
/* 感谢各位美化老师们的慷慨分享（抹泪）*/

@import url("https://fontsapi.zeoseven.com/488/main/result.css");
/* == 全局设置 & 字体== */
:root {
    --topBarBlockSize: 27px;
    --mainFontSize: 12px;
    --box-border-radius: 5px;
    --top-distance: 7px;
    --scroll-width: 5px;
    --icon-size: var(--mainFontSize);
}

body,
.text_pole:not(#completion_prompt_manager_list),
select,
textarea:not(#send_textarea),
input {
    font-family: "STDongGuanTi";
    font-weight: normal;
}

code,
code * {
    font-family: "STDongGuanTi" !important;
    font-weight: normal !important;
}

/* == 聊天主界面布局 == */
/* 二改自kakaa老师的双色盒子 */
#sheld {
    height: calc(100dvh - var(--topBarBlockSize) - var(--top-distance) - 1px);
}

#chat {
    background: transparent !important;
    background-color: transparent !important;
    backdrop-filter: none;
    border: none !important;
    overflow-y: scroll;
    align-items: center;
    max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
    padding: calc(var(--scroll-width) + 4px) 0 var(--scroll-width) var(--scroll-width);
    border-radius: 0 0 var(--box-border-radius) var(--box-border-radius);
}

@supports (-webkit-touch-callout: none) {
    #chat {
        padding-right: var(--scroll-width);
    }
}

/* 滚动条样式 */
::-webkit-scrollbar {
    width: 5px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
    background-color: #ffffff;
    box-shadow: none;
    border: 0;
}

/* == 消息气泡 == */
.mes {
    width: 95%;
    padding: 8px 12px;
    margin: 4rem auto !important;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: rgba(255, 255, 255, 0.8) !important;
    position: relative;
}

/* 气泡背景装饰 */
.mes::after {
    content: "";
    position: absolute;
    left: 0px;
    bottom: 0px;
    width: 200px;
    height: 190px;
    background-image: url('https://iili.io/fGZSe07.png');
    background-size: cover;
    background-repeat: no-repeat;
    opacity: 0.8 !important;
    pointer-events: none;
}

.mes::before {
    content: "";
    position: relative;
    left: -4px;
    bottom: 20px;
    width: 340px;
    height: 30px;
    background-image: url('https://iili.io/fVPmd9R.png');
    background-size: cover;
    background-repeat: no-repeat;
    opacity: 1 !important;
    pointer-events: none;
}

/* 用户专属气泡装饰 */
[is_user=true].mes::after {
    content: "";
    position: absolute;
    left: 230px;
    bottom: -8px;
    width: 100px;
    height: 100px;
    background-image:url('https://iili.io/fWjFmV1.png')!important;
    background-size: cover;
    background-repeat: no-repeat;
    opacity: 0.6 !important;
    pointer-events: none;
    z-index: 1;
}

/* ==头像与名字 == */
.mesAvatarWrapper {
    position: absolute;
    top: -65px !important;
    left: 75% !important;
    transform: none !important;
}

#chat .mes .avatar {
    position: relative;
    left: -40px;
    top: 15px;
    display: inline-block;
    padding: 8px;
    z-index: 1;
    transform: scale(1.25);
}

#chat .mes .avatar img {
    width: 70px;
    height: 60px;
    object-fit: cover;
    object-position: center 40%;
    border-radius: 0;
    transition: all 0.3s ease;
    z-index: 1;
}

#chat .mes .avatar::after {
    content: "";
    position: absolute;
    top: -10px;
    left: -15px;
    width: calc(300% - 35px);
    height: calc(300%);
    background-image: url("https://iili.io/fGfcfCg.png");
    background-size: contain;
    background-repeat: no-repeat;
    z-index: 999;
    pointer-events: none;
}

/* 头像选中框 */
.avatar-container.interactable.selected {
    outline: 3px solid #8ABCD1 !important;
    padding: 3px;
}

.avatar-container {
    width: 80px !important;
    height: 80px !important;
    min-width: 80px !important;
    min-height: 80px !important;
}

/* 名字栏 */
#chat .ch_name {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    top: 20px;
    padding: 8px 10px 8px 8px;
    margin-top: -20px;
    min-height: 40px;
    background-color: rgba(234, 238, 241, 0);
    border-radius: 5px;
}

/* ==消息内容与排版== */
.mes_text {
    padding: 20px 0px 40px 6px !important;
    z-index: 999;
}
/* 源自P1222老师 */
.mes_text br:first-child{
    display: none !important;
}

.mes_block {
    width: 100%;
    padding-left: 0;
}

.mes_text p {
    margin-bottom: 1em!important;
}

/* 代码块样式 */
.mes_text code {
    display: inline-block;
    background-color: #d3dbe280 !important;
    background-image: url('https://iili.io/fGYmb3l.gif');
    padding: 8px 8px;
    margin: 5px 8px 5px 0 !important;
    color: #324e7b !important;
    border: 0.9px solid #bcd4e7 !important;
    border-radius: 6px !important;
    letter-spacing: 0.3px !important;
    word-spacing: 1px !important;
    line-height: 1.4 !important;
    font-size: 1em !important;
}

/* 引用块样式 */
.mes_text blockquote {
    background: linear-gradient(135deg, #f8f9fa 20%, #e9ecef 100%) !important;
    margin: 16px 8px 20px 0 !important;
    padding: 20px 24px !important;
    border-left: 4px solid #007bff !important;
    border-radius: 4px !important;
    border: 1px solid #e9ecef !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05) !important;
    position: relative;
}

.mes_text blockquote::before {
    content: "";
    position: absolute;
    display: inline-block;
    width: 60px;
    height: 60px;
    right: 0;
    bottom: 0;
    background-image: url('https://iili.io/fW0SiLN.png');
    background-size: contain;
    background-repeat: no-repeat;
    opacity: 0.6;
}

/*思维链 */
.mes_reasoning_summary {
    padding: 0 !important;
    margin: 0px 0px !important;
}

.mes_reasoning_header {
    position: relative !important;
    top: 10px !important;
    left: -10px !important;
    width: 85% !important;
    height: 40px !important;
    color: transparent !important;
    font-size: 1em !important;
    background-color: #ffffff80 !important;
    background-image: url('https://iili.io/fW01ic7.jpg') !important;
    background-size: cover !important;
    background-position: center center !important;
}

.mes_reasoning_header.flex-container::before {
    content: "❅𝒯𝒽𝓮 𝒻𝒾𝓇𝓈𝓉 𝓈𝓃𝓸𝓌 𝒻𝒶𝓁𝓁𝓈°の";
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    color: #909fac !important;
    font-size: 1em !important;
    font-weight: 600 !important;
    letter-spacing: 1px !important;
    text-transform: uppercase !important;
    white-space: nowrap !important;
    z-index: 2 !important;
}

/* ==消息元数据 == */
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
    position: absolute !important;
    display: inline-block;
    top: 80px;
    padding: 4px 10px;
    border-radius: 16px;
    background: rgba(225, 225, 225, 0.6);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    border: 2px solid rgba(255, 255, 255, 0.5);
    color: #000000;
    font-size: 14px;
    font-weight: 500;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
    z-index: 99;
}

.mesIDDisplay { right: 230px; }
.tokenCounterDisplay { right: 175px; }
.mes_timer { right: 120px; }

.mesIDDisplay:empty,
.tokenCounterDisplay:empty,
.mes_timer:empty {
    display: none !important;
}

/* ==顶部栏== */
#top-bar {
    background-image: url('https://iili.io/fGYmb3l.gif');
    background-size: cover;
    background-color: rgba(255, 254, 248, 0.1);
    background-position: center;
    background-repeat: no-repeat;
    height: 30px;
    width: 100%;
    box-shadow: none;
}

/* 顶部图标通用样式 */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    display: block;
    margin: 5px auto 0;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 30px;
    height: 30px;
    transform: translateX(-9px) translateY(2px);
}

/* 图标交互状态 */
.drawer-icon,
.fa-bars,
#extensionsMenuButton,
.fa-paper-plane {
    opacity: 0.7 !important;
    transition: opacity 0.2s ease !important;
}

.drawer-icon:hover,
.fa-bars:hover,
#extensionsMenuButton:hover,
.fa-paper-plane:hover {
    opacity: 0.95 !important;
}

.drawer-icon:active,
.fa-bars:active,
#extensionsMenuButton:active,
.fa-paper-plane:active,
.drawer-icon.active,
.fa-bars.active,
#extensionsMenuButton.active,
.fa-paper-plane.active {
    opacity: 1 !important;
}

/* 各个按钮图标替换 */
#leftNavDrawerIcon::before,
#sys-settings-button .drawer-icon::before,
#advanced-formatting-button .drawer-icon::before,
#WI-SP-button .drawer-icon::before,
#user-settings-button .drawer-icon::before,
#logo_block .drawer-icon::before,
#backgrounds-button .drawer-icon::before,
#extensions-settings-button .drawer-icon::before,
#persona-management-button .drawer-icon::before,
#rightNavDrawerIcon::before,
#table_drawer_icon.drawer-icon::before{
    background-image: url('https://iili.io/f000Tkg.png');
}

/* ==底部输入栏== */
#send_form {
    position: relative;
    bottom: 5px;
    width: 95%;
    padding: 2px;
    border-radius: 15px;
    background-image: url('https://iili.io/fGFRJP2.gif');
    background-color: #BEEF007;
    background-blend-mode: overlay;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease;
}

#nonQRFormItems {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1px 2px;
    border-radius: 50px;
    position: relative;
}

/* 底部按钮基础 */
#options_button.fa-bars,
#extensionsMenuButton.fa-magic-wand-sparkles,
#send_but.fa-paper-plane {
    position: relative;
    font-size: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 45px;
    border: none;
    background: transparent;
    cursor: pointer;
}

#options_button.fa-bars::before,
#extensionsMenuButton.fa-magic-wand-sparkles::before,
#send_but.fa-paper-plane::before {
    content: '' !important;
    display: block;
    width: 100%;
    height: 100%;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    font-size: 0;
}

/* 选项按钮 */
#options_button.fa-bars::before {
    background-image: url('https://iili.io/f000t8F.png');
    position: absolute;
    right: 20%;
}

/* 扩展按钮 */
#extensionsMenuButton.fa-magic-wand-sparkles::before {
    background-image: url('https://iili.io/f0QwfUv.png');
    position: absolute;
    right: 18.5%;
    flex-shrink: 0;
    width: 35px !important;
    height: 40px !important;
}

/* 发送按钮 */
#send_but.fa-paper-plane::before {
    background-image: url('https://iili.io/f001jAg.png');
    width: 35px !important;
    height: 40px !important;
    position: absolute;
    right: 20%;
    top: 50%;
    transform: translateY(-50%);
}

/* 停止按钮 */
#mes_stop {
    position: absolute;
    right: 5%;
}

#mes_stop::before {
    background-image: url('') !important;
    width: 32px !important;
    height: 32px !important;
    position: absolute;
    right: 20%;
    top: 50%;
    transform: translateY(-50%);
    z-index: 2;
    opacity: 1;
}

/* 输入框 */
#send_textarea {
    position: relative;
    right: 5px;
    flex-shrink: 0;
    box-sizing: border-box;
    outline: none;
    padding: 4px;
    vertical-align: top;
    border: none !important;
    box-shadow: none !important;
    text-shadow: none !important;
}

#send_textarea::placeholder {
    color: transparent !important;
}

/* 输入框占位符装饰 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "❅₊ 𝓦𝓲𝓷𝓽𝓮𝓻 𝓓𝓪𝔂 𝓛𝓮𝓽𝓽𝓮𝓻 ₊ ❅";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-49%, -50%);
    font-size: 14px;
    pointer-events: none;
    white-space: nowrap;
    border: none !important;
}

/* QR Bar */
#send_form:focus-within #qr--bar {
    height: 40px;
    opacity: 1;
    overflow-y: auto;
    transition: all 0.5s ease;
}

#qr--bar {
    height: 0;
    opacity: 0;
    overflow: hidden;
    transition: all 0.5s ease;
}

/* == UI 组件 == */
/* 滑块 (Range Input) */
input[type="range"],
input[type="range"]:disabled {
    -webkit-appearance: none;
    filter: none;
    box-shadow: none !important;
    background-color: #c8d0d3 !important;
    height: 3px !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 22px;
    height: 22px;
    box-shadow: none;
    background-color: transparent;
    background-image: url(https://iili.io/f001jAg.png);
    background-size: cover;
    background-repeat: no-repeat;
    cursor: pointer;
    outline: none;
    border: none;
}

/* 普通输入框背景 */
input:not(input[type="range"], input[type='checkbox']) {
    background: url(https://iili.io/fMAMQ7S.png);
    background-color: #e4ecf033;
    background-size: 150% 100%;
    background-repeat: no-repeat;
    background-position: center;
}

/* 复选框 */
input[type="checkbox"] {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 20px;
    background-image: url('https://iili.io/fMRCI8N.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-color: transparent;
    border: none;
    outline: none;
    box-shadow: none;
}

input[type="checkbox"]:checked {
    background-image: url('https://iili.io/fMRCI8N.png');
}

input[type="checkbox"]:checked::before {
    width: 12px;
    height: 12px;
    box-shadow: inset 1em 1em black;
}

/* ==设置面板与扩展 == */
/* 抽屉头部与标题 */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader,
.select2-selection select2-selection--multiple,
#image_overswipe,
.J-paginationjs-size-select {
    background-image: none !important;
    background: linear-gradient(100deg, #f0f7ff33 100%) !important;
    color: #1e2732;
    border-radius: 20px !important;
    border: 1px solid #ebeee8 !important;
    backdrop-filter: blur(50px);
    transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
    position: relative;
    right: -2px;
    overflow: hidden;
}

.inline-drawer-icon {
    font-family: initial !important;
    background-image: none !important;
}

.inline-drawer-icon::before {
    content: "" !important;
    display: inline-block;
    width: 1em;
    height: 1em;
    position: relative;
    background-image: url('https://iili.io/f01W6ss.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    vertical-align: middle;
    opacity: 0.5;
}

.inline-drawer-header b {
    font-size: 12px !important;
    font-weight: 600 !important;
    position: relative;
    left: 20px;
    white-space: nowrap;
}

.inline-drawer-toggle.inline-drawer-header strong {
    margin-left: 23px;
}

/* 色框标题 */
.title_restorable,
h4:has(span[data-i18n="Miscellaneous"]),
h4[data-i18n="Character Handling"],
h4[data-i18n="Chat/Message Handling"],
h4[data-i18n="STscript Settings"],
h4.standoutHeader,
h4.standoutHeader.title_restorable,
h4.standoutHeader.justifySpaceBetween {
    background: linear-gradient(135deg, #ffffff80 100%) !important;
    color: black !important;
    border-radius: 8px !important;
    padding: 1px 8px !important;
    margin: 10px 0 !important;
    border: none !important;
}

/* 按钮与输入框背景统一 */
#openai_inline_image_quality,
#openai_reasoning_effort,
#openai_logit_bias_preset,
#settings_preset_openai,
#main_api,
#chat_completion_source,
#connection_profiles,
#example_messages_behavior,
.text_pole,
.textarea_compact,
.margin0,
.select2-selection.select2-selection--multiple,
.select2-selection.select2-selection--single,
.inline-drawer-content,
.mdHotkeys:not(#send_textarea),
.inline-drawer-header b[data-i18n="Quick Prompts Edit"],
#instruct_presets.flex1.text_pole,
#instruct_activation_regex {
    background-color: #ffffff80 !important;
    box-shadow: none !important;
}

.inline-drawer-header b[data-i18n="Quick Prompts Edit"],
#instruct_presets.flex1.text_pole,
#instruct_activation_regex {
    flex: 1;
}



/* ==预设管理器 == */
/* 感谢lazzzy Alie老师 */
ul#completion_prompt_manager_list.text_pole.ui-sortable {
    background: url('https://iili.io/fW01ic7.jpg') !important;
    background-repeat: repeat-y !important;
    background-size: 100% auto !important;
    background-position: top center !important;
    border-radius: 2px !important;
    padding: 5px 5px !important;
    margin: 10px 0 !important;
    box-shadow: 3px 0 10px rgba(150, 150, 150, 0.25) !important;
    border: 0.8px solid #e0e0e0 !important;
}

/* 已开启的提示词条目 */
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    background: linear-gradient(135deg, #ffffff 0%, #f5f7fa 100%) !important;
    border: 1px solid #12507b !important;
    border-radius: 12px !important;
    padding: 8px 12px 8px 18px !important;
    margin: 4px 0 !important;
    min-height: 36px !important;
    box-shadow: 0 1px 4px rgba(74, 144, 226, 0.5) !important;
}

/* 未开启的提示词条目 */
.completion_prompt_manager_prompt_disabled {
    border: 1px solid #cccccc !important;
    border-radius: 12px !important;
    padding: 8px 12px !important;
    margin: 4px 0 !important;
    color: #888888 !important;
    opacity: 0.8 !important;
}

.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled):hover {
    border-color: #1c6cc1 !important;
    box-shadow: 0 2px 8px rgba(28, 108, 193, 0.25) !important;
    transform: translateY(-1px) !important;
}

.completion_prompt_manager_prompt_disabled:hover {
    border-color: #a0a0a0 !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1) !important;
}

.completion_prompt_manager_prompt_buttons button {
    border: 0.8px solid #d0d0d0 !important;
    background: linear-gradient(180deg, #ffffff 0%, #f0f0f0 100%) !important;
    color: #4a90e2 !important;
}

.completion_prompt_manager_prompt_buttons button:hover {
    background: linear-gradient(180deg, #f0f0f0 0%, #e0e0e0 100%) !important;
    border-color: #4a90e2 !important;
}

/* ==左侧导航栏 == */
/* 源自formula_kelly老师 */
#left-nav-panel a, #left-nav-panel button,
#left-nav-panel span, #left-nav-panel div,
#leftNavPanel a, #leftNavPanel button,
#leftNavPanel span, #leftNavPanel div,
.left-panel a, .left-panel button, .left-panel span, .left-panel div {
    color: #000000 !important;
    text-shadow: none !important;
}

#left-nav-panel .preset_list .preset_item.selected,
#left-nav-panel .preset_list .preset_item.active,
#left-nav-panel .preset-list .preset-item:active,
#leftNavPanel .preset_list .preset_item.selected,
.left-panel .preset_list .preset_item.selected {
    background-color: #666666 !important;
    color: #000000 !important;
    font-weight: bold !important;
}

/*==收藏栏滑动 == */
/* 源自P1222老师 */
#HotSwapWrapper {
    overflow-x: auto;
    scrollbar-width: thin;
    scrollbar-color: rgba(255, 255, 255, 0.7) transparent;
    position: relative;
    --scrollbar-height: 6px;
    --scrollbar-padding: 4px;
    padding-bottom: calc(var(--scrollbar-height) + var(--scrollbar-padding));
}

#HotSwapWrapper::-webkit-scrollbar {
    height: 6px;
    position: absolute;
    bottom: -6px;
}

#HotSwapWrapper::-webkit-scrollbar-track {
    background: transparent;
    margin: 0 20px;
    border-radius: 3px;
}

#HotSwapWrapper::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.7);
    border-radius: 3px;
    min-width: 50px;
}

#HotSwapWrapper::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.9);
}

.hotswap.avatars_inline {
    min-width: max-content;
}

.hotswap.avatars_inline > .avatar.inline_avatar {
    display: inline-block;
}

#HotSwapWrapper * {
    max-width: none;
}

/* ==收藏== */
.character_select.is_fav{
    position: relative;
